import numpy as np

def detect_anomaly(value, history, sigma=3.0):
    if len(history) < 2:
        return False, 0.0
    arr = np.asarray(history, dtype=float)
    mean = arr.mean()
    std = arr.std()
    if std == 0:
        return (value != mean), 0.0
    deviation = abs(value - mean) / std
    return deviation > sigma, round(float(deviation), 4)

